/**
 * ReviewCard.tsx — Review card with Apply / Edit / Dismiss flow.
 *
 * SPEC REQUIREMENT (§6):
 * - Every AI result renders as a review card with Apply / Edit / Dismiss.
 * - The UI shows "Generated by the built-in planner" when fallback is used.
 */

import { useState } from 'react';

interface ReviewCardProps {
  title: string;
  source: 'ai' | 'fallback';
  tier?: 'simple' | 'standard' | 'special';
  initialText: string;
  estimateMinor?: number;
  applyLabel?: string;
  onApply: (editedText: string) => void;
  onDismiss: () => void;
}

export function ReviewCard({
  title,
  source,
  tier,
  initialText,
  estimateMinor,
  applyLabel = 'Apply to Deck',
  onApply,
  onDismiss,
}: ReviewCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [text, setText] = useState(initialText);

  return (
    <div className="bg-white p-5 rounded-xl border border-mist shadow-sm space-y-3">
      {/* Header with Source Badge & Tier */}
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-2">
          {tier && (
            <span
              className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${
                tier === 'special'
                  ? 'bg-rose text-white'
                  : tier === 'standard'
                    ? 'bg-teal text-white'
                    : 'bg-mist text-ink'
              }`}
            >
              {tier} tier
            </span>
          )}
          <h4 className="font-serif font-bold text-sm text-ink">{title}</h4>
        </div>

        {/* Source disclosure */}
        <span
          className={`px-2 py-0.5 rounded-full text-[10px] font-semibold ${
            source === 'fallback'
              ? 'bg-mist/80 text-ink/90 border border-mist'
              : 'bg-teal/10 text-teal border border-teal/20'
          }`}
        >
          {source === 'fallback' ? 'Generated by the built-in planner' : 'Suggested by Gemini'}
        </span>
      </div>

      {/* Content / Editor */}
      {isEditing ? (
        <div className="space-y-2">
          <textarea
            value={text}
            onChange={(e) => {
              setText(e.target.value);
            }}
            rows={3}
            className="w-full p-2.5 text-xs text-ink border border-mist rounded-md focus-visible:ring-2 focus-visible:ring-saffron"
            aria-label={`Edit ${title}`}
          />
        </div>
      ) : (
        <p className="text-xs text-ink/90 leading-relaxed">{text}</p>
      )}

      {/* Estimate label */}
      {estimateMinor !== undefined && (
        <div className="text-xs text-teal font-semibold tabular-nums">
          Estimate: ₹{(estimateMinor / 100).toLocaleString('en-IN')}{' '}
          <span className="text-[10px] font-medium text-ink/80">(editable estimate, not a quote)</span>
        </div>
      )}

      {/* Action buttons: Apply / Edit / Dismiss */}
      <div className="pt-2 border-t border-mist/40 flex items-center justify-end gap-2 text-xs">
        {isEditing ? (
          <button
            type="button"
            onClick={() => {
              setIsEditing(false);
            }}
            className="px-3 py-1.5 rounded text-ink/90 font-medium hover:bg-mist transition-colors"
          >
            Done Editing
          </button>
        ) : (
          <button
            type="button"
            onClick={() => {
              setIsEditing(true);
            }}
            className="px-3 py-1.5 rounded text-ink/90 font-medium hover:bg-mist transition-colors"
          >
            Edit
          </button>
        )}

        <button
          type="button"
          onClick={onDismiss}
          className="px-3 py-1.5 rounded text-rose font-semibold hover:bg-rose/10 transition-colors"
        >
          Dismiss
        </button>

        <button
          type="button"
          onClick={() => {
            onApply(text);
          }}
          className="px-4 py-1.5 rounded bg-teal text-white font-semibold hover:bg-teal/90 shadow-xs transition-colors"
        >
          {applyLabel}
        </button>
      </div>
    </div>
  );
}
